// Offline-model listening UI: mocked generated bytes and review acknowledgments,
// real muted browser playback. No model inference/network/user review writes.
import {writeFileSync} from "node:fs"
import {Browser, BASE_URL} from "./cdp.mjs"

const browser = await Browser.launch()
const failures = []
const check = (ok, message) => ok || failures.push(message)
try {
  const page = await browser.newPage("voice-model")
  await page.open(`${BASE_URL}/dev/voice-lab`); await page.labView('listen')
  await page.waitFor(`document.getElementById("voice-lab-status")?.dataset.state === "rendered"`, "lab readiness", 30_000)
  await page.labView('models')
  check(await page.eval(`document.querySelectorAll("[data-model-case]").length === 4`), "four public model comparisons should be present")
  await page.eval(`(() => {
    const fetch = window.fetch.bind(window), start = AudioBufferSourceNode.prototype.start;
    window.modelStarts = 0;
    AudioBufferSourceNode.prototype.start = function(...args) {
      if (this.context instanceof AudioContext) { window.modelNode = this; window.modelStarts++; }
      return start.apply(this, args);
    };
    function fixture(level) {
      const bytes = new ArrayBuffer(44+48000), data = new DataView(bytes);
      const text = (at,value) => [...value].forEach((c,i) => data.setUint8(at+i,c.charCodeAt(0)));
      text(0,"RIFF"); data.setUint32(4,48036,true); text(8,"WAVE"); text(12,"fmt ");
      data.setUint32(16,16,true); data.setUint16(20,1,true); data.setUint16(22,1,true);
      data.setUint32(24,48000,true); data.setUint32(28,96000,true); data.setUint16(32,2,true); data.setUint16(34,16,true);
      text(36,"data"); data.setUint32(40,48000,true);
      for(let i=0;i<24000;i++) data.setInt16(44+i*2,Math.round(level*32767),true);
      return bytes;
    }
    window.fetch = (url,options) => {
      if (url === "/dev/voice-lab/reviews") {
        window.modelReview = JSON.parse(options.body);
        return Promise.resolve(new Response(JSON.stringify({saved_at:new Date().toISOString()}), {status:201}));
      }
      if (!String(url).includes("/voice-lab/models/")) return fetch(url,options);
      if (window.modelFail) return Promise.resolve(new Response("missing", {status:404}));
      const response = () => new Response(fixture(String(url).includes("__original__") ? .1 : .2));
      if (window.modelHold) { window.modelHold = false; return new Promise(resolve => { window.releaseModel = () => resolve(response()); }); }
      return Promise.resolve(response());
    };
  })()`)
  await page.click("#voice-lab-model-loop")
  await page.click("#voice-lab-model-play-all")
  await page.waitFor(`document.getElementById("voice-lab-model-status").textContent.startsWith("Playing")`, "model comparison playback", 10_000)
  check(await page.eval(`{
    const data=window.modelNode.buffer.getChannelData(0);
    window.modelNode.loop && data.length===72000 && Math.abs(data[23999]-.1)<.001 && data.subarray(24000,36000).every(x=>x===0) && Math.abs(data[59999]-.2)<.001 && data.subarray(60000).every(x=>x===0);
  }`), "model comparison should preserve both clips and 250ms gaps")
  await page.click("#voice-lab-model-loop")
  await page.waitFor(`window.modelNode.context.state === "closed"`, "model natural end cleanup", 10_000)
  await page.eval(`window.modelHold = true`)
  await page.click("#voice-lab-model-play-all")
  await page.waitFor(`!!window.releaseModel`, "pending model comparison", 10_000)
  await page.labView('recovery')
  await page.eval(`window.releaseModel()`)
  await page.eval(`new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))`)
  check(await page.eval(`window.modelStarts === 1`), "leaving Models must cancel pending playback")
  await page.click("#voice-lab-recovery-loop")
  check(await page.eval(`[...document.querySelectorAll("[data-model-case] audio")].every(player=>!player.loop) && !document.getElementById("voice-lab-model-loop").checked`), "Recovery looping must not change Models looping")
  await page.labView('models')
  await page.eval(`window.modelFail = true`)
  await page.click("#voice-lab-model-play-all")
  await page.waitFor(`document.getElementById("voice-lab-model-status").textContent.includes("Could not play")`, "missing generated WAV feedback", 10_000)
  await page.eval(`window.modelFail = false`)
  await page.click("#voice-lab-model-play-all")
  await page.waitFor(`document.getElementById("voice-lab-model-status").textContent.startsWith("Playing")`, "model retry", 10_000)
  await page.eval(`{
    const player=document.querySelector("[data-model-case]:not([hidden]) audio");
    player.querySelector("source").src="/dev/voice-lab/clips/high_voice.wav"; player.load(); player.play();
  }`)
  await page.waitFor(`window.modelNode.context.state === "closed" && [...document.querySelectorAll("[data-model-case] audio")].some(player=>!player.paused)`, "native playback exclusivity", 10_000)
  await page.eval(`{
    const rating=document.getElementById("voice-lab-review-model-disguised-resemblance");
    rating.value="different"; rating.dispatchEvent(new Event("change",{bubbles:true}));
  }`)
  await page.click("#voice-lab-review-model [data-review-save]")
  await page.waitFor(`document.getElementById("voice-lab-review-model-status").dataset.state === "saved"`, "model review acknowledgment", 10_000)
  check(await page.eval(`window.modelReview.context.view === "model" && window.modelReview.context.processor === "seed_vc_v2" && window.modelReview.context.build_id.length === 64 && window.modelReview.context.source_id.length === 64 && !!window.modelReview.context.run_id`), "model review should retain exact experiment provenance")
  await page.eval(`{
    const choice=document.getElementById("voice-lab-model-choice"); choice.selectedIndex=1;
    choice.dispatchEvent(new Event("change",{bubbles:true}));
  }`)
  check(await page.eval(`[...document.querySelectorAll("[data-model-case] audio")].every(player=>player.paused) && document.getElementById("voice-lab-review-model-disguised-resemblance").value === ""`), "case changes should stop audio and separate drafts")
  if (process.env.SCREENSHOT) {
    for (const [suffix,width,height] of [["",1440,1200],["-mobile",390,844]]) {
      await page.send("Emulation.setDeviceMetricsOverride", {width,height,deviceScaleFactor:1,mobile:width===390})
      check(await page.eval(`document.documentElement.scrollWidth <= innerWidth`), "Models should fit the viewport")
      const {data} = await page.send("Page.captureScreenshot", {format:"png",captureBeyondViewport:true})
      writeFileSync(process.env.SCREENSHOT.replace(/\.png$/,`${suffix}.png`), Buffer.from(data,"base64"))
    }
  }
} finally {
  await browser.close()
}
for (const failure of failures) console.log(`✗ ${failure}`)
console.log(failures.length ? `${failures.length} model checks failed` : "voice model ok")
process.exit(failures.length ? 1 : 0)
